from pathlib import Path
def refresh_worker(old,config,argv,verify):
    value=json.loads(Path(config).read_text(encoding='utf8'))
    token=value.get('token') if isinstance(value,dict) else None
    if not isinstance(token,str) or len(token)<16 or '\0' in token:raise ValueError('worker token')
    env={**os.environ,'OPSFORGE_WORKER_TOKEN':token}
    fresh=subprocess.Popen(argv,env=env,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
    try:
        if verify(fresh) is not True:raise RuntimeError('new worker not verified')
        if old.poll() is None:
            old.terminate()
            try:old.wait(timeout=1)
            except subprocess.TimeoutExpired:old.kill();old.wait(timeout=2)
        return fresh
    except BaseException:
        if fresh.poll() is None:
            fresh.terminate()
            try:fresh.wait(timeout=1)
            except subprocess.TimeoutExpired:fresh.kill();fresh.wait(timeout=2)
        if fresh.stdout:fresh.stdout.close()
        if fresh.stderr:fresh.stderr.close()
        raise
