import sqlite3,re
from pathlib import Path
def promote(path,generation,digest):
    if type(generation) is not int or generation<0 or not isinstance(digest,str) or not re.fullmatch(r'[0-9a-f]{64}',digest):raise ValueError('generation and sha256')
    connection=sqlite3.connect(Path(path).resolve().as_uri()+'?mode=rw',uri=True,timeout=2,isolation_level=None)
    try:
        connection.execute('BEGIN IMMEDIATE')
        row=connection.execute('SELECT generation,digest FROM deployment WHERE id=1').fetchone()
        if row is None:raise ValueError('missing deployment state')
        if generation<row[0]:connection.rollback();return 'stale'
        if generation==row[0]:
            if digest!=row[1]:raise ValueError('same generation changed artifact')
            connection.rollback();return 'unchanged'
        connection.execute('UPDATE deployment SET generation=?,digest=? WHERE id=1',(generation,digest));connection.commit();return 'promoted'
    except BaseException:connection.rollback();raise
    finally:connection.close()
